using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NationalRoutesTests
{
    static WorldSession Start(string dest){var s=new WorldSession(NationalRoutes.Create());Assert.Equal(ResultCode.Accepted,s.Submit(NationalRoutes.Move(s.DiagnosticSnapshot(),"request:national",dest),s.Revision).Code);s.AdvanceTo(1);return s;}
    [Fact] public void NationwideGraphIsConnectedAndAllStopsHaveRoundTripPlans(){var w=NationalRoutes.Create();Assert.Equal(108,NationalRoutes.Nodes.Length);Assert.Equal(118,NationalRoutes.Edges.Length);foreach(var n in NationalRoutes.Nodes.Where(n=>n.Id!="castle")){Assert.NotEmpty(BranchRoutes.Plan("castle",n.Id,[],w:w));Assert.NotEmpty(BranchRoutes.Plan(n.Id,"castle",[],true,w));}}
    [Theory][InlineData("katsuyama")][InlineData("shuri")][InlineData("izuhara")][InlineData("hirado")][InlineData("yuzuki")][InlineData("oko")]
    public void IslandsUseExplicitSeaEdgesAndCannotBeReachedOnLandOnly(string destination){var w=NationalRoutes.Create();var route=BranchRoutes.Plan("castle",destination,[],w:w);Assert.Contains(route,NationalRoutes.Sea);Assert.Throws<InvalidDataException>(()=>BranchRoutes.Plan("castle",destination,NationalRoutes.Edges.Where(e=>NationalRoutes.Sea(e.Id)).Select(e=>e.Id),w:w));}
    [Theory][InlineData("nejo")][InlineData("katsuyama")][InlineData("shuri")][InlineData("izuhara")][InlineData("yuzuki")][InlineData("funai")][InlineData("edo")][InlineData("toda")]
    public void ActualOfficerCanReachDistantRegionsAndReturnReport(string destination){var s=Start(destination);var task=s.DiagnosticSnapshot().Tasks.Single();Assert.True(task.DeadlineAt>task.StartedAt);s.AdvanceTo(20000000);Assert.Equal(RegionalCampaign.Site(destination),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Contains(s.DiagnosticSnapshot().Couriers!.Missions,m=>m.Legs.Length>0);}
    [Theory][InlineData(false)][InlineData(true)]
    public void MidJourneyLandAndSeaRestorePreservesPositionCourierAndContinuation(bool sea){var s=Start("shuri");var leg=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.First(l=>NationalRoutes.Sea(l.Edge)==sea);s.AdvanceTo(leg.StartAt+(leg.EndAt-leg.StartAt)/2);var root=Path.Combine(Path.GetTempPath(),"hakutai-national-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,NationalRoutes.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(new(NationalRoutes.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));host.Current.SetPaused(false);s.AdvanceTo(20000000);host.Current.AdvanceTo(20000000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));}
    [Fact] public void LongDistanceDeadlineDoesNotReuseTheShortRegionalLimit(){var s=Start("shuri");var j=s.DiagnosticSnapshot().Branches!.Journeys.Single();Assert.True(j.Legs[^1].EndAt>1000000);Assert.True(s.DiagnosticSnapshot().Tasks.Single().DeadlineAt>j.Legs[^1].EndAt);}
    [Fact] public void RemoteClosureCannotLeakIntoTheInitialPlan(){var a=NationalRoutes.Create();var b=NationalRoutes.Create();var edge=NationalRoutes.Catalog.Edges.First(e=>e.Mode=="land").Id;b.Branches=b.Branches! with{BlockedEdges=[edge]};b.Couriers=b.Couriers! with{InitialBlocked=[edge]};var sa=new WorldSession(a);var sb=new WorldSession(b);Assert.Equal(ContractJson.Write(sa.GetBranchView(ContractFixture.Officer)),ContractJson.Write(sb.GetBranchView(ContractFixture.Officer)));Assert.Equal(NationalRoutes.Move(a,"request:privacy","shuri").WorkSeconds,NationalRoutes.Move(b,"request:privacy","shuri").WorkSeconds);}
    [Fact] public void UserApprovedInferenceDoesNotPretendToBeSurveyEvidence(){Assert.Contains("User approved approximate",NationalRoutes.Catalog.Policy);Assert.All(NationalRoutes.Catalog.Edges,e=>{Assert.Contains("inferred",e.HistoricalCertainty);Assert.NotEmpty(e.SourceIds);Assert.Contains(e.Mode,new[]{"land","sea"});});Assert.NotEqual(HistoricalRoads.Version,NationalRoutes.Version);var c=NationalRoutes.Catalog;c.Nodes[0]=c.Nodes[0] with{Name="changed"};Assert.NotEqual("changed",NationalRoutes.Catalog.Nodes[0].Name);}
    [Fact] public void PriorRegionalSaveIsNeverReinterpretedAsNational(){var s=new WorldSession(RegionalCampaign.Create());var root=Path.Combine(Path.GetTempPath(),"hakutai-national-old-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,RegionalCampaign.Create().Definitions).Save(s,"old",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,NationalRoutes.Create().Definitions).Prepare("old"));}
}
